import { users } from '../users'
import { updateStreak } from '../services/streak'

export async function completeLesson(req, res) {
  const user = await users.get(req.user.id)
  const updated = updateStreak(user, new Date())
  await users.save(updated)
  res.json({ streak: updated.streak })
}

export function dayKey(date: Date): string {
  return date.toISOString().slice(0, 10)
}

export function updateStreak(user: User, playedAt: Date): User {
  const today = dayKey(playedAt)
  const yesterday = dayKey(new Date(playedAt.getTime() - 24 * 60 * 60 * 1000))

  if (user.lastPlayedDay === today) return user
  const streak = user.lastPlayedDay === yesterday ? user.streak + 1 : 1
  return { ...user, streak, lastPlayedDay: today }
}

export function StreakBadge({ streak }: { streak: number }) {
  if (streak === 0) return null
  return <span className="streak">{streak} day streak</span>
}

export async function searchLessons(query: string): Promise<string[]> {
  const res = await fetch(`/api/lessons/search?q=${encodeURIComponent(query)}`)
  if (!res.ok) throw new Error(`Search failed: ${res.status}`)
  return res.json()
}

import { useEffect, useState } from 'react'
import { searchLessons } from '../api/lessons'
import { ResultsList } from './ResultsList'

export function SearchBox() {
  const [query, setQuery] = useState('')
  const [results, setResults] = useState<string[]>([])

  useEffect(() => {
    if (!query) return
    searchLessons(query).then(setResults)
  }, [query])

  return (
    <>
      <input value={query} onChange={(e) => setQuery(e.target.value)} />
      <ResultsList items={results} />
    </>
  )
}

export function ResultsList({ items }: { items: string[] }) {
  if (items.length === 0) return <p>No lessons found.</p>
  return <ul>{items.map((item) => <li key={item}>{item}</li>)}</ul>
}

